INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 18, 'theory', 'SSH, VPN, and Tunnels');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 0, 'Connecting over SSH, you see "REMOTE HOST IDENTIFICATION HAS CHANGED". What should you do?', '["Delete known_hosts right away", "Ask the administrator whether the key change was planned or the server may have been replaced", "Ignore it and continue", "Reboot the computer"]', 1, 'Either the host key was changed or the server was replaced: decide after checking, not by reflex.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 1, 'What does the ssh-copy-id command do?', '["Copies the private key to the server", "Generates a host key", "Copies files over SSH", "Adds your public key to authorized_keys on the server"]', 3, 'The private key never leaves your computer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 2, 'What is ssh -J (ProxyJump) for?', '["To speed up login", "To turn off encryption", "To reach internal-network servers through one open bastion", "To copy keys"]', 2, 'The client logs in to the bastion first, and from there TCP goes to the target; internal servers are not published outside.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 3, 'Why is the MTU inside a VPN tunnel smaller than outside?', '["The original packet is packed into a new one, and the packing headers take up space", "The tunnel is slower", "The provider limits the size", "The MTU does not change"]', 0, 'Without lowering the MTU, large packets will not fit and will vanish (see the diagnostics chapter).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 18, 4, 'How does a split tunnel differ from a full one?', '["Everything goes into the VPN, including ordinary internet", "Only traffic to corporate networks goes into the VPN, the rest goes directly", "The VPN uses two keys", "A split tunnel is not encrypted"]', 1, 'A full tunnel sends everything into the VPN; a split one saves the corporate gateway''s resources.');
